import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"双调·清江引秋思","description":"","frontmatter":{"title":"双调·清江引秋思","date":"2026-11-11T00:00:00.000Z","seq":2,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/双调·清江引秋思.md","filePath":"blogs/元曲·张可久/双调·清江引秋思.md"}'),o={name:"blogs/元曲·张可久/双调·清江引秋思.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="双调·清江引秋思" tabindex="-1">双调·清江引秋思 <a class="header-anchor" href="#双调·清江引秋思" aria-label="Permalink to &quot;双调·清江引秋思&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">自从玉关人去也，寂寞银屏夜。</p><p class="poem-stanza">风寒白藕花，露冷青桐叶，雁儿未来书再写。</p><p class="poem-stanza">幽居红尘是非不到我，茅屋秋风破。</p><p class="poem-stanza">山村小过活，老砚闲工课，疏篱外玉梅三四朵。</p><p class="poem-stanza">桐柏山中松风小楼香缥缈，一曲寻仙操。</p><p class="poem-stanza">秋风玉兔寒，野树金猿啸，白云半天山月小。</p><p class="poem-stanza">湖山避暑好山尽将图画写，诗会白云社。</p><p class="poem-stanza">桃笙卷浪花，茶乳翻冰叶，荷香月明人散也。</p><p class="poem-stanza">春思二首杜鹃几声烟树暖，风雨相撺断。</p><p class="poem-stanza">梨花月未圆，柳絮春将半，夜长可怜归梦短。</p><p class="poem-stanza">绣针懒拈闲素手，倦枕金钗溜。</p><p class="poem-stanza">莺啼绿柳春，燕舞红帘昼，东风院落人病酒。</p><p class="poem-stanza">九日湖上西风又吹湖上柳，画舫携红袖。</p><p class="poem-stanza">鸥眠野水闲，蝶舞秋花瘦，风流醉翁不在酒。</p><p class="poem-stanza">山居春枕门前好山云占了，尽日无人到。</p><p class="poem-stanza">松风响翠涛，槲叶烧丹灶，先生醉眠春自老。</p><p class="poem-stanza">春晚二首黄昏闭门谁笑语，燕子飞不去。</p><p class="poem-stanza">珠帘溅雨花，翠坞埋烟树，酒醒五更闻杜宇。</p><p class="poem-stanza">离愁困人帘未卷，上下飞双燕。</p><p class="poem-stanza">孤云带雨痕，暗水流花片，湖边日长春去远。</p><p class="poem-stanza">湖上晚望东西往来船斗蚁，拍手胡姬醉。</p><p class="poem-stanza">歌声落照边，塔影孤云际，荷风夜凉天似水。</p><p class="poem-stanza">秋怀西风信来家万里，问我归期未？雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
